mapper.select:
SELECT fc.figure_id, c.id, c.name, g.id AS genre_id, g.name AS genre_name FROM figure_character fc JOIN genre_character c ON c.user_id = fc.user_id AND c.id = fc.character_id JOIN genre g ON g.user_id = c.user_id AND g.id = c.genre_id WHERE fc.user_id = #{userId} AND fc.figure_id IN
#{figureId}
ORDER BY fc.figure_id, c.id
